window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-d9afd12c588f41c1"]={"versions": [{"id": "FIG-d9afd12c588f41c1", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des Metamodells für das AUTOSAR-Software-Component-Template (TPS SoftwareComponentTemplate). Das Diagramm definiert die Struktur von Instanzreferenzen (<code>InstanceRef</code>) zur Adressierung und Abbildung von Teilschnittstellen bzw. Elementen zusammengesetzter Implementierungsdatentypen (<code>ImplementationDataType</code>) im Kontext von Variablen-Prototypen (<code>VariableDataPrototype</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst folgende Klassen und Beziehungen:</p>\n<ul class=\"fig-list\">\n<li><code>ImplementationDataTypeSubElementRef</code> (Spezialisierung von <code>SubElementRef</code>): Bildet eine Instanzreferenz (<code>«instanceRef»</code>) auf ein Ziel-Element <code>+implementationDataTypeElement [1]</code> vom Typ <code>ImplementationDataTypeElement</code>. Zudem aggregiert <code>ArVariableInImplementationDataInstanceRef</code> genau ein solches Element über die Komposition <code>+implementationDataTypeElement [1]</code>.</li>\n<li><code>ImplementationDataTypeElement</code> (spezialisiert <code>Identifiable</code>): Repräsentiert ein Element eines strukturierten oder Array-Datentyps.</li>\n<li>Attribute: <code>arraySizeSemantics: ArraySizeSemanticsEnum [0..1]</code>, <code>arraySize: PositiveInteger [0..1]</code> (mit Stereotyp <code>«atpVariation»</code>).</li>\n<li>Rekursive Komposition: Aggregiert über <code>+subElement [0..*] {ordered}</code> (mit Stereotyp <code>«atpVariation»</code>) weitere <code>ImplementationDataTypeElement</code>-Instanzen.</li>\n<li><code>ImplementationDataType</code> (spezialisiert <code>AutosarDataType</code>, <code>AtpBlueprint</code>, <code>AtpBlueprintable</code>):</li>\n<li>Attribut: <code>typeEmitter: NameToken [0..1]</code>.</li>\n<li>Komposition: Beinhaltet über <code>+subElement [0..*] {ordered}</code> (mit Stereotyp <code>«atpVariation»</code>) untergeordnete <code>ImplementationDataTypeElement</code>-Instanzen.</li>\n<li><code>AutosarDataType</code> (spezialisiert <code>ARElement</code>, <code>AtpType</code>): Abstrakte Basisklasse aller AUTOSAR-Datentypen.</li>\n<li><code>DataPrototype</code> / <code>AutosarDataPrototype</code>: Typisiert über die Assoziation <code>+type [1] {redefines atpType}</code> mit Stereotyp <code>«isOfType»</code> auf <code>AutosarDataType</code>.</li>\n<li><code>VariableDataPrototype</code> (spezialisiert <code>AutosarDataPrototype</code>).</li>\n<li><code>ArVariableInImplementationDataInstanceRef</code>:</li>\n<li>Assoziation <code>+rootVariableDataPrototype [0..1]</code> zu <code>VariableDataPrototype</code>.</li>\n<li>Assoziation <code>+contextDataPrototype [0..*] {ordered}</code> zu <code>ImplementationDataTypeElement</code>.</li>\n<li>Assoziation <code>+targetDataPrototype [1]</code> zu <code>ImplementationDataTypeElement</code>.</li>\n<li>Komposition <code>+implementationDataTypeElement [1]</code> zu <code>ImplementationDataTypeSubElementRef</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne Verhaltens- oder Sequenzdiagrammelemente. Es beschreibt die deklarative Navigation zur Pfad-Adressierung: Ausgehend von einem optionalen Wurzel-Variablen-Prototyp (<code>rootVariableDataPrototype</code>) wird über eine geordnete Kette von Kontext-Elementen (<code>contextDataPrototype</code>) hierarchisch bis zum Ziel-Element (<code>targetDataPrototype</code>) innerhalb der Typstruktur eines zusammengesetzten Implementierungsdatentyps navigiert. Variabilität an <code>subElement</code> und <code>arraySize</code> ermöglicht die typstrukturelle Konfiguration zur Entwurfs- bzw. Generierungszeit.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ für Werkzeugentwickler, Codegeneratoren und AUTOSAR-Modellierer bei der Erstellung konsistenter Instanzreferenzen auf Felder oder Array-Elemente innerhalb von <code>ImplementationDataType</code>. Die geordneten Assoziationen <code>{ordered}</code> erzwingen eine strikte Einhaltung der Hierarchiefolge vom Wurzel-Element bis zum Blattelement (<code>targetDataPrototype</code>). Variabilitätsmarker (<code>«atpVariation»</code>) erfordern die Auswertung von Systemspezifikationen und Parametern zur Auflösung varianter Datenstrukturen.</p>"}, {"id": "FIG-aed360504ca0b70e", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des Metamodells für das AUTOSAR-Software-Component-Template (TPS SoftwareComponentTemplate). Das Diagramm definiert die Struktur von Instanzreferenzen (<code>InstanceRef</code>) zur Adressierung und Abbildung von Teilschnittstellen bzw. Elementen zusammengesetzter Implementierungsdatentypen (<code>ImplementationDataType</code>) im Kontext von Variablen-Prototypen (<code>VariableDataPrototype</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst folgende Klassen und Beziehungen:</p>\n<ul class=\"fig-list\">\n<li><code>ImplementationDataTypeSubElementRef</code> (Spezialisierung von <code>SubElementRef</code>): Bildet eine Instanzreferenz (<code>«instanceRef»</code>) auf ein Ziel-Element <code>+implementationDataTypeElement [1]</code> vom Typ <code>ImplementationDataTypeElement</code>. Zudem aggregiert <code>ArVariableInImplementationDataInstanceRef</code> genau ein solches Element über die Komposition <code>+implementationDataTypeElement [1]</code>.</li>\n<li><code>ImplementationDataTypeElement</code> (spezialisiert <code>Identifiable</code>): Repräsentiert ein Element eines strukturierten oder Array-Datentyps.</li>\n<li>Attribute: <code>arraySizeSemantics: ArraySizeSemanticsEnum [0..1]</code>, <code>arraySize: PositiveInteger [0..1]</code> (mit Stereotyp <code>«atpVariation»</code>).</li>\n<li>Rekursive Komposition: Aggregiert über <code>+subElement [0..*] {ordered}</code> (mit Stereotyp <code>«atpVariation»</code>) weitere <code>ImplementationDataTypeElement</code>-Instanzen.</li>\n<li><code>ImplementationDataType</code> (spezialisiert <code>AutosarDataType</code>, <code>AtpBlueprint</code>, <code>AtpBlueprintable</code>):</li>\n<li>Attribut: <code>typeEmitter: NameToken [0..1]</code>.</li>\n<li>Komposition: Beinhaltet über <code>+subElement [0..*] {ordered}</code> (mit Stereotyp <code>«atpVariation»</code>) untergeordnete <code>ImplementationDataTypeElement</code>-Instanzen.</li>\n<li><code>AutosarDataType</code> (spezialisiert <code>ARElement</code>, <code>AtpType</code>): Abstrakte Basisklasse aller AUTOSAR-Datentypen.</li>\n<li><code>DataPrototype</code> / <code>AutosarDataPrototype</code>: Typisiert über die Assoziation <code>+type [1] {redefines atpType}</code> mit Stereotyp <code>«isOfType»</code> auf <code>AutosarDataType</code>.</li>\n<li><code>VariableDataPrototype</code> (spezialisiert <code>AutosarDataPrototype</code>).</li>\n<li><code>ArVariableInImplementationDataInstanceRef</code>:</li>\n<li>Assoziation <code>+rootVariableDataPrototype [0..1]</code> zu <code>VariableDataPrototype</code>.</li>\n<li>Assoziation <code>+contextDataPrototype [0..*] {ordered}</code> zu <code>ImplementationDataTypeElement</code>.</li>\n<li>Assoziation <code>+targetDataPrototype [1]</code> zu <code>ImplementationDataTypeElement</code>.</li>\n<li>Komposition <code>+implementationDataTypeElement [1]</code> zu <code>ImplementationDataTypeSubElementRef</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne Verhaltens- oder Sequenzdiagrammelemente. Es beschreibt die deklarative Navigation zur Pfad-Adressierung: Ausgehend von einem optionalen Wurzel-Variablen-Prototyp (<code>rootVariableDataPrototype</code>) wird über eine geordnete Kette von Kontext-Elementen (<code>contextDataPrototype</code>) hierarchisch bis zum Ziel-Element (<code>targetDataPrototype</code>) innerhalb der Typstruktur eines zusammengesetzten Implementierungsdatentyps navigiert. Variabilität an <code>subElement</code> und <code>arraySize</code> ermöglicht die typstrukturelle Konfiguration zur Entwurfs- bzw. Generierungszeit.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ für Werkzeugentwickler, Codegeneratoren und AUTOSAR-Modellierer bei der Erstellung konsistenter Instanzreferenzen auf Felder oder Array-Elemente innerhalb von <code>ImplementationDataType</code>. Die geordneten Assoziationen <code>{ordered}</code> erzwingen eine strikte Einhaltung der Hierarchiefolge vom Wurzel-Element bis zum Blattelement (<code>targetDataPrototype</code>). Variabilitätsmarker (<code>«atpVariation»</code>) erfordern die Auswertung von Systemspezifikationen und Parametern zur Auflösung varianter Datenstrukturen.</p>"}, {"id": "FIG-8ec8bf6880b538bb", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des Metamodells für das AUTOSAR-Software-Component-Template (TPS SoftwareComponentTemplate). Das Diagramm definiert die Struktur von Instanzreferenzen (<code>InstanceRef</code>) zur Adressierung und Abbildung von Teilschnittstellen bzw. Elementen zusammengesetzter Implementierungsdatentypen (<code>ImplementationDataType</code>) im Kontext von Variablen-Prototypen (<code>VariableDataPrototype</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst folgende Klassen und Beziehungen:</p>\n<ul class=\"fig-list\">\n<li><code>ImplementationDataTypeSubElementRef</code> (Spezialisierung von <code>SubElementRef</code>): Bildet eine Instanzreferenz (<code>«instanceRef»</code>) auf ein Ziel-Element <code>+implementationDataTypeElement [1]</code> vom Typ <code>ImplementationDataTypeElement</code>. Zudem aggregiert <code>ArVariableInImplementationDataInstanceRef</code> genau ein solches Element über die Komposition <code>+implementationDataTypeElement [1]</code>.</li>\n<li><code>ImplementationDataTypeElement</code> (spezialisiert <code>Identifiable</code>): Repräsentiert ein Element eines strukturierten oder Array-Datentyps.</li>\n<li>Attribute: <code>arraySizeHandling: ArraySizeHandlingEnum [0..1]</code>, <code>arraySizeSemantics: ArraySizeSemanticsEnum [0..1]</code>, <code>arraySize: PositiveInteger [0..1]</code> (mit Stereotyp <code>«atpVariation»</code>).</li>\n<li>Rekursive Komposition: Aggregiert über <code>+subElement [0..*] {ordered}</code> (mit Stereotyp <code>«atpVariation»</code>) weitere <code>ImplementationDataTypeElement</code>-Instanzen.</li>\n<li><code>ImplementationDataType</code> (spezialisiert <code>AutosarDataType</code>, <code>AtpBlueprint</code>, <code>AtpBlueprintable</code>):</li>\n<li>Attribute: <code>dynamicArraySizeProfile: String [0..1]</code>, <code>typeEmitter: NameToken [0..1]</code>.</li>\n<li>Komposition: Beinhaltet über <code>+subElement [0..*] {ordered}</code> (mit Stereotyp <code>«atpVariation»</code>) untergeordnete <code>ImplementationDataTypeElement</code>-Instanzen.</li>\n<li><code>AutosarDataType</code> (spezialisiert <code>ARElement</code>, <code>AtpType</code>): Abstrakte Basisklasse aller AUTOSAR-Datentypen.</li>\n<li><code>DataPrototype</code> / <code>AutosarDataPrototype</code>: Typisiert über die Assoziation <code>+type [1] {redefines atpType}</code> mit Stereotyp <code>«isOfType»</code> auf <code>AutosarDataType</code>.</li>\n<li><code>VariableDataPrototype</code> (spezialisiert <code>AutosarDataPrototype</code>).</li>\n<li><code>ArVariableInImplementationDataInstanceRef</code>:</li>\n<li>Assoziation <code>+rootVariableDataPrototype [0..1]</code> zu <code>VariableDataPrototype</code>.</li>\n<li>Assoziation <code>+contextDataPrototype [0..*] {ordered}</code> zu <code>ImplementationDataTypeElement</code>.</li>\n<li>Assoziation <code>+targetDataPrototype [1]</code> zu <code>ImplementationDataTypeElement</code>.</li>\n<li>Komposition <code>+implementationDataTypeElement [1]</code> zu <code>ImplementationDataTypeSubElementRef</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne Verhaltens- oder Sequenzdiagrammelemente. Es beschreibt die deklarative Navigation zur Pfad-Adressierung: Ausgehend von einem optionalen Wurzel-Variablen-Prototyp (<code>rootVariableDataPrototype</code>) wird über eine geordnete Kette von Kontext-Elementen (<code>contextDataPrototype</code>) hierarchisch bis zum Ziel-Element (<code>targetDataPrototype</code>) innerhalb der Typstruktur eines zusammengesetzten Implementierungsdatentyps navigiert. Variabilität an <code>subElement</code> und <code>arraySize</code> ermöglicht die typstrukturelle Konfiguration zur Entwurfs- bzw. Generierungszeit.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ für Werkzeugentwickler, Codegeneratoren und AUTOSAR-Modellierer bei der Erstellung konsistenter Instanzreferenzen auf Felder oder Array-Elemente innerhalb von <code>ImplementationDataType</code>. Die Attribute <code>arraySizeHandling</code> an <code>ImplementationDataTypeElement</code> und <code>dynamicArraySizeProfile</code> an <code>ImplementationDataType</code> spezifizieren zusätzlich die Handhabung variabler bzw. dynamischer Arraygrößen und Profile in der Implementierung. Die geordneten Assoziationen <code>{ordered}</code> erzwingen eine strikte Einhaltung der Hierarchiefolge vom Wurzel-Element bis zum Blattelement (<code>targetDataPrototype</code>). Variabilitätsmarker (<code>«atpVariation»</code>) erfordern die Auswertung von Systemspezifikationen und Parametern zur Auflösung varianter Datenstrukturen.</p>"}], "trans": [{"from": "FIG-d9afd12c588f41c1", "to": "FIG-aed360504ca0b70e", "fr": "R4.0.3", "tr": "R4.1.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-aed360504ca0b70e", "to": "FIG-8ec8bf6880b538bb", "fr": "R4.1.3", "tr": "R4.2.2", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><code>ImplementationDataTypeElement</code>: Attribut <code>arraySizeHandling: ArraySizeHandlingEnum [0..1]</code> ergänzt.</li>\n<li><code>ImplementationDataType</code>: Attribut <code>dynamicArraySizeProfile: String [0..1]</code> ergänzt.</li>\n</ul>"}]};
